function home(){const year=new Date().getFullYear();return `<section class="hero"><div class="hero-mark">F1</div><h1>Fórmula 1 <span>Insights</span></h1><p>Guias originais, calendário ${year}, estratégias e simuladores para acompanhar a F1 com mais contexto.</p><a class="button about-cta" href="#guias">Explorar os guias</a></section><section class="grid">${[['▦','blue','Calendário','Veja as corridas e os resultados da temporada '+year+'.','calendario'],['♧','yellow','Estratégias','Aprenda sobre pneus, pit stops e ultrapassagens.','estrategias'],['⚑','red','Simuladores','Escolha entre planejar a estratégia ou disputar uma corrida.','simulador'],['?','green','Quiz','Teste seu conhecimento sobre pilotos da Fórmula 1.','quiz']].map(x=>`<a class="feature-card" href="#${x[4]}"><div class="icon-tile icon-${x[1]}">${x[0]}</div><h2>${x[2]}</h2><p>${x[3]}</p><span class="access">Acessar <span>›</span></span></a>`).join('')}</section><section class="card home-editorial"><h2>Entenda o que acontece além da bandeirada</h2><p>Uma corrida é decidida por mais do que velocidade: a janela de parada, o ritmo dos pneus, o tráfego e as neutralizações podem mudar a estratégia. Os guias do F1 Insights explicam esses conceitos com exemplos e linguagem direta para você acompanhar as decisões na pista.</p><a class="access" href="#guias">Leia os guias de Fórmula 1 <span>›</span></a></section>`}
function about(){return `<section class="about-hero"><div class="hero-mark">F1</div><p class="eyebrow">SOBRE O PROJETO</p><h1>F1 <span>Insights</span></h1><p class="about-lead">A Fórmula 1 é cheia de estratégia, tecnologia e histórias. Este espaço ajuda você a acompanhar tudo isso de um jeito claro e fácil de curtir.</p><a class="button about-cta" href="#estrategias">Começar a explorar</a></section><section class="grid about-grid"><article class="card about-card"><span>📚</span><h2>Entenda a corrida</h2><p>Aprenda sobre pneus, pit stops, ultrapassagens e decisões que mudam uma prova.</p></article><article class="card about-card"><span>🏁</span><h2>Experimente a estratégia</h2><p>Teste cenários no simulador e acompanhe como suas escolhas afetam a corrida.</p></article><article class="card about-card"><span>🎯</span><h2>Aprenda brincando</h2><p>Explore o calendário, descubra curiosidades e desafie seus conhecimentos no quiz.</p></article></section><section class="author-section card"><div class="author-avatar" aria-hidden="true">🏎️</div><div class="author-content"><p class="eyebrow">QUEM ESTÁ POR TRÁS</p><h2>Sobre o autor</h2><p>O F1 Insight foi idealizado por um fã, eu, Miguel, com vontade de aproximar mais pessoas do esporte. Aqui, o foco é aprender sobre estratégias, acompanhar as corridas, se divertir nos simuladores e explorar a categoria de forma interativa.</p></div></section><section class="contact-section" id="contato"><div class="contact-heading"><p class="eyebrow">VAMOS CONVERSAR</p><h2>Contato</h2><p>Encontre o projeto e acompanhe as próximas novidades.</p></div><div class="grid contact-grid"><article class="card contact-card"><span class="contact-icon contact-github"><svg viewBox="0 0 24 24" role="img" aria-label="GitHub"><path fill="currentColor" d="M12 .297c-6.63 0-12 5.373-12 12 0 5.303 3.438 9.8 8.205 11.385.6.113.82-.258.82-.577 0-.285-.01-1.04-.015-2.04-3.338.724-4.042-1.61-4.042-1.61-.546-1.387-1.333-1.756-1.333-1.756-1.09-.745.083-.729.083-.729 1.205.085 1.84 1.237 1.84 1.237 1.07 1.834 2.807 1.304 3.492.997.108-.776.42-1.305.763-1.594-2.665-.3-5.467-1.333-5.467-5.93 0-1.31.467-2.38 1.236-3.22-.124-.303-.536-1.524.117-3.176 0 0 1.008-.322 3.3 1.23.957-.266 1.983-.399 3.003-.404 1.02.005 2.047.138 3.006.404 2.29-1.552 3.295-1.23 3.295-1.23.655 1.652.243 2.873.12 3.176.77.84 1.233 1.91 1.233 3.22 0 4.61-2.807 5.625-5.48 5.92.43.37.815 1.102.815 2.222 0 1.604-.014 2.896-.014 3.29 0 .322.216.694.825.576C20.565 21.795 24 17.3 24 12 24 5.373 18.627 0 12 0z"/></svg></span><div><h3>GitHub</h3><p>Código e novidades do projeto</p><a class="contact-placeholder" href="https://github.com/miguel-flp" target="_blank" rel="noopener noreferrer">Visite meu GitHub ↗</a></div></article><article class="card contact-card"><span class="contact-icon contact-coffee"><svg viewBox="0 0 24 24" role="img" aria-label="Buy Me a Coffee"><path fill="currentColor" d="M6.898 0 5.682 2.799H3.877v2.523h.695L5.277 9.8H4.172l1.46 8.23.938-.01L7.512 24h8.918l.062-.4.88-5.58.888.01 1.46-8.231h-1.056l.705-4.477h.756V2.8h-1.918L16.99 0H6.898zm.528.805h9.043l.771 1.78H6.652l.774-1.78zm-2.75 2.797H19.32v.92H4.676v-.92zm.453 6.998h13.635l-1.176 6.62-5.649-.06-5.636.06-1.174-6.62z"/></svg></span><div><h3>Buy Me a Coffee</h3><p>Apoie o desenvolvimento do F1 Insights</p><a class="contact-placeholder" href="https://buymeacoffee.com/miguel_filipe" target="_blank" rel="noopener noreferrer">Apoie no Buy Me a Coffee ↗</a></div></article><article class="card contact-card"><span class="contact-icon contact-email" aria-hidden="true">✉️</span><div><h3>E-mail</h3><p>Fale comigo diretamente</p><a class="contact-placeholder" href="mailto:filipemiguelfilipemiguel@gmail.com">filipemiguelfilipemiguel@gmail.com ↗</a></div></article></div></section><p class="about-note">Projeto independente feito para fãs. Não é afiliado à Fórmula 1 nem à FIA.</p>`}
function calendar(){const year=new Date().getFullYear(),live=calendarData?.year===year,fallback=year===2026?races.map((r,i)=>({round:i+1,name:r[1],locality:r[2],country:'',flag:r[0],date:r[3],winner:r[4]})):[],items=live?calendarData.races:fallback,completed=items.filter(r=>r.winner).length,nextIndex=items.findIndex(r=>!r.winner),dateLabel=value=>{const d=new Date(value);return Number.isNaN(d.getTime())?value:new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(d).replace('.','')};let sourceLabel=live?`Dados de ${calendarData.source} · atualizados ${new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(new Date(calendarData.updatedAt))}`:(calendarMode==='loading'||calendarMode==='idle'?'Buscando os dados mais recentes…':items.length?'Exibindo cópia local de reserva.':'Não foi possível carregar o calendário. Tente novamente mais tarde.');return `<div class="page-head"><h1>Calendário ${year}</h1><p>${completed} de ${items.length} corridas concluídas${nextIndex>=0?` · próxima: ${items[nextIndex].name}`:items.length?' · temporada concluída':''}</p><div class="progress-wrap" aria-label="${completed} de ${items.length} corridas concluídas"><div class="progress-fill" style="width:${items.length?completed/items.length*100:0}%"></div></div><p class="calendar-update" aria-live="polite">${sourceLabel}${calendarMode==='fallback'&&items.length?' <button class="calendar-refresh" data-calendar-refresh>Atualizar agora</button>':''}</p></div><section class="race-list">${items.map((r,i)=>`<article class="race-row ${r.winner?'':'race-upcoming'}"><span class="race-country">${r.flag||String(r.round||i+1).padStart(2,'0')}</span><span class="race-check" aria-label="${r.winner?'Concluída':'A realizar'}">${r.winner?'✓':'◷'}</span><div class="race-info"><strong><span style="color:#68778d;font-weight:500;margin-right:8px">R${r.round||i+1}</span>${r.name}</strong><small>⌖ ${r.locality||r.country||''}${r.locality&&r.country?', ':''}${r.locality&&r.country?r.country:''}${r.circuit?` · ${r.circuit}`:''}</small><span class="race-result">${r.winner?`Vencedor: ${r.winner}`:i===nextIndex?'Próxima corrida':'Agendada'}</span></div><time class="race-date">${dateLabel(r.date)}</time></article>`).join('')||'<article class="card"><p>O calendário desta temporada ainda não está disponível.</p></article>'}</section><aside class="guide-disclaimer">Dados de calendário de <a href="https://whenstherace.com/" target="_blank" rel="noopener">When’s the Race</a>, com dados de <a href="https://github.com/f1db/f1db" target="_blank" rel="noopener">F1DB</a> e horários de <a href="https://github.com/sportstimes/f1" target="_blank" rel="noopener">sportstimes/f1</a> (CC BY 4.0). Nomes dos GPs localizados pelo F1 Insights. Feed independente, sem vínculo oficial com a F1. Consulte também a <a href="https://www.formula1.com/en/racing/${year}" target="_blank" rel="noopener">programação oficial da Fórmula 1</a>.</aside>`}
function escapeCalendarText(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function portugueseRaceName(name,round,year){if(year!==2026)return name;const pt=['GP da Austrália','GP da China','GP do Japão','GP de Miami','GP do Canadá','GP de Mônaco','GP de Barcelona-Catalunha','GP da Áustria','GP da Grã-Bretanha','GP da Bélgica','GP da Hungria','GP dos Países Baixos','GP da Itália','GP da Espanha','GP do Azerbaijão','GP do Bahrein na Malásia','GP de Singapura','GP dos Estados Unidos','GP da Cidade do México','GP de São Paulo','GP de Las Vegas','GP do Catar','GP de Abu Dhabi'];return pt[round-1]||name}
async function loadCalendar(force=false){const year=new Date().getFullYear();if(calendarRequestYear===year&&(!force||Date.now()-calendarFetchedAt<3600000))return;calendarRequestYear=year;calendarMode='loading';try{const response=await fetch('https://whenstherace.com/schedule.json',{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Feed indisponível');const feed=await response.json();if(!Array.isArray(feed))throw new Error('Formato inválido');const racesForYear=feed.filter(r=>r.utc&&new Date(r.utc).getUTCFullYear()===year);if(!racesForYear.length)throw new Error('Calendário do ano ainda não publicado');calendarData={year,source:'When’s the Race',updatedAt:new Date().toISOString(),races:racesForYear.map(r=>({round:Number(r.round),name:escapeCalendarText(portugueseRaceName(r.name,Number(r.round),year)),circuit:escapeCalendarText(r.circuit||''),locality:'',country:escapeCalendarText(r.country||''),flag:escapeCalendarText(r.flag||''),date:r.utc,winner:escapeCalendarText(typeof r.result?.winner==='string'?r.result.winner:r.result?.winner?.name||r.result?.winner?.driver||'')}))};calendarFetchedAt=Date.now();calendarMode='live'}catch(error){calendarMode='fallback';console.info('Calendário ao vivo indisponível; usando dados locais.',error)}if(page()==='calendario')render()}
function strategies(){return `<div class="page-head"><h1>Estratégias de F1</h1><p>Clique em um tema para aprender de forma simples.</p></div><section class="grid strategy-grid">${topics.map((t,i)=>`<article class="card strategy-card" tabindex="0" role="button" data-topic="${i}"><span class="strategy-emoji">${t.icon}</span><h2>${t.title}</h2><p>${t.desc}</p></article>`).join('')}</section>`}
function guides(){return ['<div class="page-head"><h1>Guias de Fórmula 1</h1><p>Explicações originais para entender melhor o que acontece antes, durante e depois da corrida.</p></div><section class="guide-list">','<article class="card guide-article"><p class="guide-kicker">01 · FIM DE SEMANA</p><h2>Como funciona um fim de semana de Grande Prêmio?</h2><p>O fim de semana combina sessões de treino, classificação e corrida. Os treinos ajudam as equipes a avaliar o carro e os pneus em diferentes condições. A classificação define a ordem de largada do Grande Prêmio: cada piloto tenta fazer voltas rápidas dentro do formato eliminatório usado naquele evento.</p><p>Alguns eventos usam o formato Sprint, que altera a programação e inclui uma corrida curta com sua própria sessão classificatória. Por isso, a sequência e os horários podem variar de uma etapa para outra. Confira o calendário do evento específico antes de planejar o que assistir.</p><p>Na corrida principal, a posição no grid é apenas o começo: largada, ritmo, tráfego, paradas e neutralizações podem mudar a ordem.</p></article>','<article class="card guide-article"><p class="guide-kicker">02 · PNEUS E STINTS</p><h2>O que a equipe observa ao escolher pneus?</h2><p>Um stint é o trecho da corrida feito com o mesmo jogo de pneus. Em pista seca, os compostos slicks variam em aderência e durabilidade. O macio tende a favorecer o ritmo por menos tempo; o duro costuma sustentar stints mais longos; o médio fica entre os dois. Essa comparação muda conforme as características do circuito, a temperatura e o modo como cada carro usa os pneus.</p><p>As equipes acompanham a degradação, ou seja, a perda de desempenho ao longo das voltas. Se o tempo por volta cai, parar pode recuperar ritmo, mas a equipe também calcula o tempo perdido no pit lane e o tráfego na volta de saída.</p><p>Não existe uma estratégia de uma ou duas paradas que seja a melhor em todas as pistas. A decisão depende do ritmo observado e da distância que ainda falta.</p></article>','<article class="card guide-article"><p class="guide-kicker">03 · PIT WINDOW</p><h2>Undercut, overcut e janela de parada</h2><p>A janela de parada é o período em que trocar os pneus pode fazer sentido para a estratégia. Ela considera a vida útil esperada do composto, a queda de ritmo e o custo de percorrer o pit lane. Também importa onde o carro vai voltar: sair atrás de um grupo lento pode apagar o ganho de pneus novos.</p><p>No undercut, o piloto para antes do rival e tenta aproveitar os pneus novos e a pista livre para ganhar tempo. No overcut, ele permanece na pista depois da parada do adversário, tentando fazer voltas competitivas enquanto o outro aquece os pneus novos. As duas opções dependem da distância entre os carros, do ritmo relativo e do tráfego.</p><p>Uma equipe também pode escolher estender o stint, aceitando perder posição momentânea para buscar vantagem de pneus mais tarde. O termo da estratégia só faz sentido quando comparado com a situação real da pista.</p><p class="guide-source">Referência: <a href="https://www.formula1.com/en/latest/article/f1-glossary-p-t.GBhLQtpeu9b8LrK5VM0F1" target="_blank" rel="noopener">glossário oficial da F1 sobre pit window</a>.</p></article>','<article class="card guide-article"><p class="guide-kicker">04 · NEUTRALIZAÇÕES</p><h2>Safety Car e Virtual Safety Car</h2><p>O Safety Car entra quando a direção de prova precisa reduzir o ritmo e agrupar os carros enquanto uma situação é resolvida. O Virtual Safety Car (VSC) também reduz a velocidade, mas os pilotos precisam respeitar um tempo mínimo por trecho, sem formar a fila atrás do carro de segurança.</p><p>Uma neutralização pode reduzir o tempo relativo perdido numa parada, já que todos estão andando mais devagar. Ainda assim, ela não torna o pit stop gratuito: a posição de pista, o tráfego na saída e o momento em que a corrida recomeça continuam importantes. Uma parada fora da janela planejada pode obrigar a equipe a fazer outra depois.</p><p>Por isso, estrategistas preparam cenários antes da largada e definem sinais que justificariam mudar o plano inicial.</p></article>','<article class="card guide-article"><p class="guide-kicker">05 · ULTRAPASSAGEM EM 2026</p><h2>Como funciona o modo de ultrapassagem?</h2><p>Em 2026, o modo de ultrapassagem substitui o DRS. Quando o piloto está dentro de um segundo do carro à frente no ponto de detecção, o sistema pode liberar energia elétrica adicional para ajudar na tentativa de passar.</p><p>O recurso não garante a ultrapassagem. O piloto e a equipe ainda precisam decidir onde usar a energia, como proteger a bateria para o trecho seguinte e como posicionar o carro para chegar perto do adversário. A reta disponível, a saída da curva anterior e a resposta do rival também influenciam.</p><p>Essa decisão faz parte de uma disputa maior de energia ao longo da volta, e não de um simples botão que sempre produz uma manobra.</p><p class="guide-source">Referência: <a href="https://www.formula1.com/en/latest/article/f1-glossary-k-o.6g2hrWHA2pyxbXoe8FT9Db" target="_blank" rel="noopener">glossário oficial da F1 sobre Overtake Mode</a>.</p></article>','<article class="card guide-article"><p class="guide-kicker">06 · LEITURA DE CORRIDA</p><h2>Como perceber se uma parada está dando resultado?</h2><p>Imagine dois carros separados por dois segundos. O primeiro para e volta atrás de um grupo lento; o segundo permanece na pista. Mesmo com pneus novos, o primeiro pode perder tempo preso no tráfego. Por isso, a equipe compara o ritmo por volta dos dois carros e estima a posição depois que ambos fizerem suas paradas.</p><p>Uma volta isolada não basta para concluir que os pneus acabaram. A equipe observa uma sequência de voltas, desconta fatores como tráfego e bandeiras amarelas e compara o ritmo com os carros em condições parecidas. A queda consistente pode indicar degradação; uma volta lenta atrás de outro carro pode ser apenas perda de tempo no ar sujo.</p><p>Para acompanhar a transmissão, repare em três pistas: diferença para o rival direto, voltas desde a última parada e espaço livre na saída dos boxes. Se esses fatores favorecem pneus novos, o undercut ganha força. Se a pista estiver congestionada, ficar mais tempo pode preservar a posição.</p><p>Esse raciocínio não revela a decisão exata da equipe, porque dados de temperatura, desgaste e desempenho são internos. Ele ajuda o fã a entender por que duas equipes podem escolher planos diferentes com os mesmos pneus.</p><p class="guide-source">Leitura complementar: <a href="https://www.formula1.com/en/latest/article/f1-glossary-u-z.5JSlDsnyvYmbK0TCjTs7KB" target="_blank" rel="noopener">glossário oficial da F1 sobre undercut</a> e <a href="https://www.formula1.com/en/latest/article/watch-the-insiders-guide-to-f1-strategists.6VT3445ugVd0bh85Pw5slO" target="_blank" rel="noopener">visão de estrategistas da F1</a>.</p></article></section><aside class="guide-disclaimer">Material educativo independente. Regras e formatos podem mudar; consulte as informações oficiais de cada Grande Prêmio.</aside>'].join('')}
function privacy(){return `<div class="page-head"><h1>Política de Privacidade</h1><p>Como o F1 Insights trata informações e o que mudará quando anúncios forem ativados.</p></div><article class="card privacy-content"><p class="privacy-updated">Última atualização: 31 de outubro de 2026</p><h2>Sobre o site</h2><p>O F1 Insights é um projeto independente criado por Miguel para explicar aspectos da Fórmula 1 e oferecer ferramentas interativas para fãs. Não é afiliado à Fórmula 1 nem à FIA.</p><h2>Informações tratadas atualmente</h2><p>O site não exige cadastro, não tem formulário de contato e não usa, neste momento, Google Analytics nem anúncios. As escolhas feitas nos simuladores são processadas no navegador durante a sessão; o site não mantém um perfil de usuário nem envia essas escolhas para um servidor próprio.</p><p>A hospedagem está planejada na Vercel. Quando o site for publicado, a Vercel poderá processar informações técnicas de acesso, como endereço IP e dados de navegação, para operar, proteger e manter seus serviços, conforme sua política de privacidade e a configuração efetivamente usada. Consulte o <a href="https://vercel.com/legal/privacy-notice" target="_blank" rel="noopener">aviso de privacidade da Vercel</a>. Esta descrição deverá ser revisada após a publicação para refletir a configuração real.</p><h2>Publicidade e cookies</h2><p>O Google AdSense ainda não foi instalado. Se anúncios forem ativados, o Google e seus parceiros poderão usar cookies, identificadores, endereços IP ou tecnologias semelhantes para exibir e medir anúncios, inclusive anúncios personalizados, conforme as configurações e as escolhas de consentimento aplicáveis.</p><p>Antes de ativar anúncios, esta política será atualizada com os serviços efetivamente utilizados e serão disponibilizados os controles de consentimento exigidos para os públicos e regiões atendidos. Saiba <a href="https://policies.google.com/technologies/partner-sites" target="_blank" rel="noopener">como o Google usa dados em sites parceiros</a> e ajuste a <a href="https://adssettings.google.com/" target="_blank" rel="noopener">personalização de anúncios do Google</a>.</p><h2>Links externos e calendário</h2><p>Os guias podem apontar para páginas oficiais da Fórmula 1. Ao abrir um site externo, o tratamento de dados passa a seguir as políticas daquele serviço.</p><p>Quando o calendário é aberto, o navegador solicita dados atualizados ao feed público <a href="https://whenstherace.com/" target="_blank" rel="noopener">When’s the Race</a>. Esse serviço recebe a solicitação e pode tratar dados técnicos conforme suas próprias políticas. O feed utiliza dados do F1DB e horários de sportstimes/f1, que são creditados na página do calendário; o site não consulta esses projetos diretamente durante a navegação.</p><h2>Contato e atualizações</h2><p>O responsável pelo projeto é Miguel. Você pode encontrar o autor no <a href="https://github.com/miguel-flp" target="_blank" rel="noopener noreferrer">GitHub</a> ou apoiar o projeto pelo <a href="https://buymeacoffee.com/miguel_filipe" target="_blank" rel="noopener noreferrer">Buy Me a Coffee</a>; os dois links também aparecem na seção Sobre. Para falar diretamente com Miguel, escreva para <a href="mailto:filipemiguelfilipemiguel@gmail.com">filipemiguelfilipemiguel@gmail.com</a>. Antes de ativar anúncios, esta política será revisada para refletir a hospedagem e os serviços realmente utilizados.</p><p>Esta página descreve o estado atual do projeto e não substitui uma revisão jurídica nem a configuração de uma plataforma de consentimento quando ela for necessária.</p></article>`}
function quiz(){if(quizIndex>=questions.length)return `<section class="quiz-wrap card quiz-finish"><div class="out-icon">🏁</div><h1>Quiz concluído!</h1><div class="score">${score}<span style="font-size:25px;color:#94a3b8"> / ${questions.length}</span></div><p>${score>=8?'Mandou muito bem! Você já entende bastante de F1.':score>=5?'Boa corrida! Continue aprendendo sobre F1.':'Uma volta de cada vez — tente de novo e melhore seu resultado.'}</p><button class="button" id="retry-quiz">Jogar novamente</button></section>`;const q=questions[quizIndex];return `<section class="quiz-wrap"><div class="quiz-top"><div><h1>Quiz de F1</h1><span class="quiz-count">10 perguntas sorteadas do nosso banco</span></div><span class="quiz-count">${quizIndex+1} / ${questions.length}</span></div><div class="quiz-progress"><span style="width:${(quizIndex/questions.length)*100}%"></span></div><div class="card question"><h2>${q.q}</h2></div><div class="answers">${q.a.map((v,i)=>`<button class="answer" data-answer="${i}"><span class="letter">${'ABCD'[i]}.</span>${v}</button>`).join('')}</div><div class="feedback" aria-live="polite"></div><button class="button next-question" style="display:none">${quizIndex===questions.length-1?'Ver resultado':'Próxima pergunta'} →</button></section>`}
function shuffle(items){for(let i=items.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[items[i],items[j]]=[items[j],items[i]]}return items}
function beginQuiz(){let selection,signature;do{selection=shuffle([...questionBank]).slice(0,10);signature=selection.map(q=>q.q).join('|')}while(signature===lastQuizSignature);lastQuizSignature=signature;questions=selection.map(item=>{const correctAnswer=item.a[item.correct],answers=shuffle([...item.a]);return {...item,a:answers,correct:answers.indexOf(correctAnswer)}});quizIndex=0;score=0;answered=false}
function simulator(){if(simulatorMode==='select')return `<div class="page-head"><h1>Simuladores</h1><p>Escolha como quer participar da corrida.</p></div><section class="grid simulator-choice-grid"><button class="card simulator-choice" data-sim-mode="strategy"><span class="choice-icon">🧠</span><h2>Simulador de Estratégia</h2><p>Escolha pneus e condições e analise sua decisão de corrida.</p><span class="access">Abrir simulador <span>›</span></span></button><button class="card simulator-choice" data-sim-mode="race"><span class="choice-icon">🏎️</span><h2>Simulador de Corrida</h2><p>Escolha piloto, pista e pneus. Corra, acompanhe posições e decida quando parar.</p><span class="access">Começar corrida <span>›</span></span></button></section><aside class="guide-disclaimer">Os simuladores são experiências recreativas com modelos simplificados. Tempos, desgaste e posições são ilustrativos; não representam telemetria, previsões ou recomendações de equipes reais.</aside>`;if(simulatorMode==='strategy')return `<button class="back-link" data-sim-back>← Voltar aos simuladores</button><div class="page-head"><h1>Simulador de Estratégia</h1><p>Escolha suas opções e veja como elas podem influenciar a corrida.</p></div><section class="sim-layout"><form class="card sim-form" id="sim-form"><label>Condição da pista<select name="weather"><option value="dry">Seca e estável</option><option value="hot">Muito quente</option><option value="rain">Chuva se aproximando</option><option value="safety">Safety Car na pista</option></select></label><label>Pneu para começar<select name="tyre"><option value="medium">Médio</option><option value="soft">Macio</option><option value="hard">Duro</option></select></label><label>Volta atual: <span id="lap-value">18</span><input name="lap" type="range" min="1" max="55" value="18" /></label><button class="button" type="submit">Analisar estratégia</button></form><article class="card sim-out" id="sim-result"><span class="out-icon">🏎️</span><h2>Sua equipe está esperando</h2><p>Defina as condições ao lado e analise a melhor decisão para este momento da corrida.</p></article></section>`;return raceState?raceScreen():raceSetup()}
function raceSetup(){return `<button class="back-link" data-sim-back>← Voltar aos simuladores</button><div class="page-head"><h1>Simulador de Corrida</h1><p>Monte seu grid e assuma o comando durante a prova.</p></div><form class="race-config" id="race-config"><fieldset class="picker-fieldset"><legend>Escolha seu piloto</legend><div class="choice-grid driver-picker">${featuredDrivers.map((p,i)=>{const d=drivers[p.index];return `<label class="choice-card driver-choice"><input type="radio" name="driver" value="${p.index}" ${p.index===3?'checked':''}><span class="choice-emoji">${p.emoji}</span><span class="choice-copy"><b>${d[0]}</b><small>${d[1]} · ${p.tag}</small></span><span class="choice-check">✓</span></label>`}).join('')}</div></fieldset><fieldset class="picker-fieldset"><legend>Escolha a pista</legend><div class="choice-grid track-picker">${raceTracks.map((t,i)=>`<label class="choice-card track-choice"><input type="radio" name="track" value="${i}" ${i===0?'checked':''}><span class="choice-emoji">${t.emoji}</span><span class="choice-copy"><b>${t.name.split(' · ')[0]}</b><small>${t.name.includes(' · ')?t.name.split(' · ')[1]:'Circuito de rua'}</small></span><span class="choice-check">✓</span></label>`).join('')}</div></fieldset><div class="race-config-bottom"><label>Distância: <strong><span id="race-lap-value">12</span> voltas</strong><input name="laps" type="range" min="8" max="30" value="12" /></label><fieldset class="picker-fieldset tire-picker"><legend>Pneu para largar</legend><div class="tire-choice-grid"><label class="tire-choice"><input type="radio" name="tyre" value="soft"><span class="tire-dot soft-dot"></span><b>Macio</b><small>Mais rápido</small></label><label class="tire-choice"><input type="radio" name="tyre" value="medium" checked><span class="tire-dot medium-dot"></span><b>Médio</b><small>Equilibrado</small></label><label class="tire-choice"><input type="radio" name="tyre" value="hard"><span class="tire-dot hard-dot"></span><b>Duro</b><small>Mais resistente</small></label></div></fieldset></div><button class="button race-start-button" type="submit">▶ Largar</button></form>`}
function raceTireWear(s){const player=s.field.find(x=>x.player),lifeFactor=player.tire==='soft'?.38:player.tire==='medium'?.57:.78,estimatedStint=s.totalLaps*lifeFactor/s.track.wear;return Math.min(100,Math.round(player.tireAge/estimatedStint*100))}
function raceScreen(){const s=raceState,ranked=[...s.field].sort((a,b)=>a.time-b.time),playerPosition=ranked.findIndex(x=>x.player)+1,remaining=s.totalLaps-s.currentLap,wear=raceTireWear(s),wearColor=wear>=80?'#ef454b':wear>=55?'#efb400':'#12a65a';return `<button class="back-link" data-race-exit>← Sair para simuladores</button><div class="page-head race-heading"><div><h1>${s.finished?'Corrida finalizada':s.track.name}</h1><p>${s.driver[0]} · ${s.track.name}</p></div><div class="race-position">${s.finished?'Resultado':'Sua posição'} <strong>P${playerPosition}</strong></div></div><section class="card race-progress-card"><div class="lap-label"><strong>Volta ${s.currentLap} / ${s.totalLaps}</strong><span>${remaining} ${remaining===1?'volta restante':'voltas restantes'}</span></div><div class="race-progress"><span style="width:${s.currentLap/s.totalLaps*100}%"></span></div><div class="tire-wear-widget"><div><b>Desgaste estimado do pneu</b><span>${wear}% · ${wear>=80?'perto do limite':wear>=55?'desgaste moderado':'boa condição'}</span></div><div class="tire-wear-track"><span style="width:${wear}%;background:${wearColor}"></span></div><small>Estimativa simplificada baseada no composto e na pista.</small></div><div class="race-status"><span>Pneu: <b>${tireName(s.playerTire)}</b> · ${s.playerTireAge} voltas</span><span>Paradas: <b>${s.playerStops}</b> · Ritmo: <b>${paceName(s.pace)}</b></span></div></section>${s.awaitingStrategy?strategyDecision():''}<section class="card race-leaderboard"><div class="leaderboard-title"><h2>Posições</h2><span>${s.finished?'Classificação final':'Atualizado a cada volta'}</span></div><div class="table-scroll"><table><thead><tr><th>Pos.</th><th>Piloto</th><th>Equipe</th><th>Pneu</th><th>Paradas</th><th>Diferença</th></tr></thead><tbody>${ranked.map((item,i)=>`<tr class="${item.player?'player-row':''}"><td><b>${i+1}</b></td><td>${item.player?'★ ':''}${item.driver[0]}</td><td>${item.driver[1]}</td><td>${tireName(item.tire)}</td><td>${item.stops}</td><td>${i===0?'Líder':`+${(item.time-ranked[0].time).toFixed(1)} s`}</td></tr>`).join('')}</tbody></table></div></section><div class="race-controls">${s.finished?'':s.awaitingStrategy?'':`<button class="button" data-race-pause>${s.running?'Ⅱ Pausar':'▶ Continuar'}</button>`}<button class="button secondary" data-race-exit>Sair da corrida</button></div>${s.finished?`<div class="race-finish-note">${s.driver[0]} terminou em <b>P${playerPosition}</b>. <button class="button" data-race-new>Nova corrida</button></div>`:''}`}
function strategyDecision(){return `<form class="card race-strategy" id="race-strategy"><div class="strategy-prompt-title"><span>🛠️</span><div><h2>Momento da estratégia</h2><p>A corrida pausou para sua decisão na volta ${raceState.currentLap}.</p></div></div><div class="strategy-options"><label class="radio-option"><input type="radio" name="stop" value="yes" checked> Parar nos boxes</label><label class="radio-option"><input type="radio" name="stop" value="no"> Seguir na pista</label><label>Trocar para<select name="tyre"><option value="soft">Macio</option><option value="medium" selected>Médio</option><option value="hard">Duro</option></select></label><label>Ritmo para o próximo trecho<select name="pace"><option value="attack">Ofensivo</option><option value="moderate" selected>Moderado</option><option value="defend">Defensivo</option></select></label></div><button class="button" type="submit">Confirmar estratégia e continuar</button></form>`}
function render(){const p=page();app.innerHTML=p==='guias'?guides():p==='privacidade'?privacy():p==='calendario'?calendar():p==='estrategias'?strategies():p==='quiz'?quiz():p==='simulador'?simulator():p==='sobre'?about():home();setNav();wire();if(p==='calendario'&&calendarData?.year!==new Date().getFullYear())loadCalendar()}
function wire(){document.querySelectorAll('[data-topic]').forEach(el=>{const open=()=>{const t=topics[+el.dataset.topic];document.querySelector('#topic-content').innerHTML=`<div class="strategy-emoji">${t.icon}</div><h2>${t.title}</h2>${t.body}`;document.querySelector('#topic-dialog').showModal();lockPageScroll()};el.addEventListener('click',open);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}})});document.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>chooseAnswer(+b.dataset.answer)));const retry=document.querySelector('#retry-quiz');if(retry)retry.onclick=()=>{beginQuiz();render()};document.querySelectorAll('[data-sim-mode]').forEach(b=>b.onclick=()=>{simulatorMode=b.dataset.simMode;raceState=null;render()});document.querySelectorAll('[data-sim-back]').forEach(b=>b.onclick=()=>{clearInterval(raceTimer);raceState=null;simulatorMode='select';render()});const form=document.querySelector('#sim-form');if(form){form.lap.oninput=()=>document.querySelector('#lap-value').textContent=form.lap.value;form.onsubmit=e=>{e.preventDefault();simulate(form)}}const config=document.querySelector('#race-config');if(config)config.onsubmit=e=>{e.preventDefault();startRace(config)};document.querySelectorAll('[data-race-pause]').forEach(b=>b.onclick=()=>{if(raceState.running){raceState.running=false;clearInterval(raceTimer);render()}else resumeRace()});document.querySelectorAll('[data-race-exit]').forEach(b=>b.onclick=()=>{clearInterval(raceTimer);raceState=null;simulatorMode='select';render()});const decision=document.querySelector('#race-strategy');if(decision)decision.onsubmit=e=>{e.preventDefault();makeStrategyDecision(decision)};const newRace=document.querySelector('[data-race-new]');if(newRace)newRace.onclick=()=>{raceState=null;render()}}
let pageScrollStyles;function lockPageScroll(){if(pageScrollStyles)return;pageScrollStyles={html:document.documentElement.style.overflow,body:document.body.style.overflow};document.documentElement.style.overflow='hidden';document.body.style.overflow='hidden'}function unlockPageScroll(){if(!pageScrollStyles)return;document.documentElement.style.overflow=pageScrollStyles.html;document.body.style.overflow=pageScrollStyles.body;pageScrollStyles=null}
function chooseAnswer(n){if(answered)return;answered=true;const q=questions[quizIndex];if(n===q.correct)score++;document.querySelectorAll('.answer').forEach((b,i)=>{b.disabled=true;if(i===q.correct)b.classList.add('correct');else if(i===n)b.classList.add('incorrect')});document.querySelector('.feedback').textContent=(n===q.correct?'✅ Isso mesmo! ':'💡 Quase! ')+q.explain;const next=document.querySelector('.next-question');next.style.display='inline-block';next.onclick=()=>{quizIndex++;answered=false;render()}}
function simulate(form){const data=new FormData(form),weather=data.get('weather'),tyre=data.get('tyre'),lap=+data.get('lap');let title,body,trigger,tag;if(weather==='safety'){title='Avalie a parada sob Safety Car';body=`Na volta ${lap}, a neutralização reduz a perda de tempo relativa nos boxes, mas não torna a parada gratuita. A decisão precisa proteger a posição de pista e encaixar no plano de stints.`;trigger='Compare a perda menor no pit lane com o tráfego na saída e o risco de precisar parar de novo. Aproveite a janela se ela já estiver aberta; evite uma parada extra só porque o Safety Car entrou.';tag='Safety Car · oportunidade com condição'}else if(weather==='rain'){title='Escolha o momento da transição';body=`Na volta ${lap}, trate a chuva como uma decisão de timing: uma parada cedo demais pode obrigar a voltar aos slicks; tarde demais pode custar aderência e tempo por volta.`;trigger='Confirme que a pista está molhada de forma consistente antes de trocar. Compare a perda de ritmo nos slicks com o tempo de aquecimento dos intermediários e evite decidir pela previsão isolada.';tag='Chuva · espere o sinal da pista'}else if(weather==='hot'){title='Proteja o ritmo do stint';body=`Na volta ${lap}, calor elevado aumenta o risco de degradação térmica. Priorize voltas consistentes e evite derrapagens; antecipe a parada apenas quando a perda de ritmo começar a custar mais que o pit stop.`;trigger='A janela fica interessante quando o ritmo cai de forma sustentada. Antes de parar, verifique se o retorno será em ar limpo: sair atrás de carros lentos pode anular o ganho dos pneus novos.';tag='Calor · controle e janela de parada'}else if(tyre==='soft'){title='Converta o ritmo em posição';body=`Na volta ${lap}, use o ritmo do macio para atacar ou abrir margem enquanto ele está competitivo. Se estiver próximo de um rival, uma parada antecipada pode criar um undercut — desde que a volta de saída seja limpa.`;trigger='Pare quando o ganho esperado nas voltas com pneus novos superar a perda no pit lane e no tráfego. Se não houver espaço livre à frente, estender o stint pode ser melhor que voltar preso atrás de outro carro.';tag='Macio · ataque com janela definida'}else if(tyre==='hard'){title='Estenda o stint sem ceder a posição';body=`Na volta ${lap}, o duro permite manter o carro na pista por mais tempo. Isso pode abrir um overcut se o rival perder tempo aquecendo pneus novos, mas estender demais transforma durabilidade em perda de ritmo.`;trigger='Compare suas voltas recentes com as do rival e proteja a posição se ele tentar o undercut. Faça a parada quando o tempo perdido na pista superar a vantagem de permanecer fora.';tag='Duro · stint longo, ritmo monitorado'}else{title='Mantenha opções abertas';body=`Na volta ${lap}, o médio permite escolher entre cobrir a parada de um rival ou estender o stint. A melhor resposta depende do ritmo relativo, da distância para o adversário e do tráfego previsto na saída dos boxes.`;trigger='Se o rival estiver próximo e houver ar limpo após a parada, considere cobrir o undercut. Se seus pneus ainda sustentarem o ritmo e os pneus novos demorarem a aquecer, o overcut pode valer mais.';tag='Médio · decisão guiada pelo rival'}const tireEffect=weather==='rain'?`O pneu ${tireName(tyre).toLowerCase()} é um slick de pista seca: costuma funcionar bem no seco, mas perde aderência quando há água acumulada. Se a pista molhar de verdade, avalie intermediários ou pneus de chuva.`:tyre==='soft'?'O macio tende a dar mais aderência e ritmo, mas se desgasta mais rápido; com calor, essa perda pode acelerar.':tyre==='hard'?'O duro tende a durar mais e ajuda em stints longos, mas pode levar mais tempo para atingir a temperatura ideal.':'O médio busca equilibrar aderência e duração, oferecendo flexibilidade sem o pico de ritmo do macio nem a longevidade do duro.';document.querySelector('#sim-result').innerHTML=`<span class="out-icon">🏁</span><h2>${title}</h2><p class="strategy-main">${body}</p><div class="strategy-callout"><strong>Ponto de decisão</strong><p>${trigger}</p></div><p><strong>Como o pneu ${tireName(tyre).toLowerCase()} afeta:</strong> ${tireEffect}</p><span class="strategy-pill">${tag}</span>`}
function tireName(tire){return tire==='soft'?'Macio':tire==='hard'?'Duro':'Médio'}function paceName(pace){return pace==='attack'?'Ofensivo':pace==='defend'?'Defensivo':'Moderado'}
function startRace(form){clearInterval(raceTimer);const data=new FormData(form),driver=drivers[+data.get('driver')],track=raceTracks[+data.get('track')],totalLaps=Math.max(8,Math.min(30,+data.get('laps')||12)),startingTire=data.get('tyre'),fieldDrivers=shuffle([driver,...shuffle(drivers.filter(d=>d!==driver)).slice(0,9)]);raceState={driver,track,totalLaps,currentLap:0,running:true,awaitingStrategy:false,finished:false,playerTire:startingTire,playerTireAge:0,playerStops:0,pace:'moderate',strategyLaps:[Math.max(2,Math.round(totalLaps/3)),Math.max(3,Math.round(totalLaps*2/3))],field:shuffle(fieldDrivers).map((d,i)=>({driver:d,player:d===driver,time:i*.18,basePace:(Math.random()-.5)*.5,tire:d===driver?startingTire:['soft','medium','hard'][Math.floor(Math.random()*3)],tireAge:0,stops:0,aiPitAt:Math.round(totalLaps*(.42+Math.random()*.16))}))};simulatorMode='race';render();resumeRace()}
function resumeRace(){if(!raceState||raceState.finished||raceState.awaitingStrategy)return;raceState.running=true;clearInterval(raceTimer);render();raceTimer=setInterval(raceTick,1100)}
function raceTick(){const s=raceState;if(!s||!s.running)return;s.currentLap++;for(const car of s.field){if(!car.player&&car.stops===0&&car.aiPitAt===s.currentLap){car.time+=19;car.stops++;car.tire=car.tire==='soft'?'medium':car.tire==='medium'?'hard':'medium';car.tireAge=0}const ageIncrement=car.player&&s.pace==='attack'?1.25:1;car.tireAge+=ageIncrement;const playerPace=car.player?(s.pace==='attack'?.43:s.pace==='defend'?-.12:0):0;const wearFactor=car.tire==='soft'?.055:car.tire==='medium'?.036:.024;const paceWear=car.player?(s.pace==='attack'?.018:s.pace==='defend'?-.006:0):0;const variance=(Math.random()-.5)*.45*s.track.passing;car.time+=s.track.lapSeconds+car.basePace+car.tireAge*wearFactor+paceWear-playerPace+variance}const player=s.field.find(x=>x.player);s.playerTire=player.tire;s.playerTireAge=Math.floor(player.tireAge);s.playerStops=player.stops;if(s.currentLap>=s.totalLaps){s.finished=true;s.running=false;clearInterval(raceTimer);render();return}if(s.strategyLaps.includes(s.currentLap)){s.awaitingStrategy=true;s.running=false;clearInterval(raceTimer);render();return}render()}
function makeStrategyDecision(form){const data=new FormData(form),player=raceState.field.find(x=>x.player);if(data.get('stop')==='yes'){player.time+=19;player.stops++;player.tire=data.get('tyre');player.tireAge=0}raceState.playerTire=player.tire;raceState.playerTireAge=Math.floor(player.tireAge);raceState.playerStops=player.stops;raceState.pace=data.get('pace');raceState.awaitingStrategy=false;resumeRace()}
app.addEventListener('input',e=>{if(e.target.name==='laps'){const output=document.querySelector('#race-lap-value');if(output)output.textContent=e.target.value}});document.querySelector('.menu-toggle').addEventListener('click',e=>{const n=document.querySelector('.nav'),open=n.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open))});document.querySelector('.dialog-close').onclick=()=>document.querySelector('#topic-dialog').close();document.querySelector('#topic-dialog').addEventListener('close',unlockPageScroll);document.querySelector('#topic-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});let activePage=page();if(activePage==='quiz')beginQuiz();window.addEventListener('hashchange',()=>{const nextPage=page();if(nextPage==='quiz'&&activePage!=='quiz')beginQuiz();if(nextPage!=='quiz'){quizIndex=0;score=0;answered=false}if(nextPage!=='simulador'){clearInterval(raceTimer);raceState=null;simulatorMode='select'}activePage=nextPage;render();window.scrollTo(0,0)});document.addEventListener('click',e=>{if(e.target.closest('[data-calendar-refresh]')){calendarRequestYear=0;loadCalendar(true)}});setInterval(()=>{if(page()==='calendario')loadCalendar(true)},3600000);render();
